from pathlib import Path
import re
root=Path(__file__).resolve().parents[1]
home=(root/'dist/index.html').read_text(encoding='utf-8')
head=home.split('<body>')[0]
header=re.search(r'<header[\s\S]*?</header>',home)[0].replace('href="#','href="/#')
footer=re.search(r'<footer[\s\S]*?</footer>',home)[0].replace('href="#','href="/#')
def write(slug,title,content):
 h=re.sub(r'<title>.*?</title>',f'<title>{title} — Rasio Agency</title>',head)
 (root/f'dist/{slug}.html').write_text(h+'<body class="info-page"><a class="skip-link" href="#main-content">Lewati ke konten utama</a>'+header+'<main id="main-content">'+content+'</main>'+footer+'<script src="/navigation.js?v=6"></script></body></html>',encoding='utf-8')
steps=[
 ('Pilih layanan dan desain','Mulai dari Rasio Store atau Rasio Profile. Pilih template langsung dari koleksi, atau tentukan desain setelah memilih domain.'),
 ('Tentukan domain website','Di homepage, ketik nama lengkap seperti bisnisanda.com. Di halaman pemesanan, cukup ketik nama bisnis lalu pilih ekstensi yang tersedia.'),
 ('Sesuaikan kebutuhan toko','Untuk Rasio Store, Anda dapat menambahkan Rasio AI Insight seharga Rp500.000/tahun. AI chatbot sudah termasuk dalam paket pre-made.'),
 ('Isi data dan lakukan pembayaran','Lengkapi nama bisnis, penanggung jawab, WhatsApp, dan email. Periksa pilihan serta biaya sebelum membayar. Tidak perlu membuat akun manual.'),
 ('Kirim materi dan review website','Tim menghubungi Anda dalam 1 × 24 jam setelah pembayaran. Siapkan logo, copywriting, foto, dan produk agar setup serta review berjalan lancar.'),
 ('Website aktif dan siap dikelola','Website pre-made aktif dalam 1–2 × 24 jam setelah pemesanan. Anda menerima akses CMS atau dashboard, email bisnis, dan panduan penggunaan.')]
cards=''.join(f'<article class="tutorial-card"><span>{i:02}</span><h2>{t}</h2><p>{c}</p><i class="flow-arrow" aria-hidden="true">→</i></article>' for i,(t,c) in enumerate(steps,1))
write('tutorial','Tutorial pemesanan',f'''<section class="info-hero"><div class="shell"><p class="eyebrow">Tutorial / pemesanan pre-made</p><h1>Dari memilih desain hingga<br /><mark class="marker">website siap digunakan.</mark></h1><p>Ikuti enam langkah berikut. Anda memilih kebutuhan bisnisnya, tim Rasio membantu setup dan memandu pengelolaannya.</p></div></section><div class="shell tutorial-grid">{cards}</div><div class="shell tutorial-notes"><article><p class="eyebrow">Setelah website aktif</p><h2>Kelola konten lewat CMS.</h2><p>Rasio Profile: ubah teks, gambar, dan logo. Rasio Store: kelola produk, stok, dan pesanan. Maintenance teknis sudah termasuk selama langganan aktif.</p><a class="secondary-button" href="/#template">Lihat template website →</a></article><article><p class="eyebrow">Untuk kebutuhan khusus</p><h2>Website, ERP, atau software custom?</h2><p>Mulai dengan konsultasi. Kami menyusun fitur, biaya, dan jadwal berdasarkan cakupan proyek. Estimasi aktivasi pre-made tidak berlaku untuk pengembangan custom.</p><a class="secondary-button" href="/layanan-custom.html">Pelajari Rasio Custom →</a></article></div>''')
write('portofolio','Portofolio dan preview desain','''<section class="info-hero"><div class="shell"><p class="eyebrow">Portofolio / preview karya</p><h1>Jelajahi tampilan website<br /><mark class="marker">dan software dari Rasio.</mark></h1><p>Koleksi ini menampilkan preview desain dan prototipe. Belum ditampilkan sebagai proyek klien yang telah diluncurkan.</p></div></section><div class="shell portfolio-grid"><article class="portfolio-card"><div class="portfolio-art"><img src="/assets/kanasari-store.png" alt="Preview desain toko online Kanasari" /></div><span class="dummy-badge">Preview desain · E-commerce</span><h2>Kanasari</h2><p>Tampilan toko fashion dengan katalog produk dan pengalaman belanja yang membawa identitas brand.</p><a class="secondary-button" href="/order.html?type=store&amp;template=Kanasari">Gunakan template →</a></article><article class="portfolio-card"><div class="portfolio-art"><div class="portfolio-mono"><small>MONO® / CREATIVE COMPANY</small><strong>Ideas made<br />visible.</strong></div></div><span class="dummy-badge">Preview desain · Company profile</span><h2>Mono</h2><p>Company profile untuk bisnis kreatif dan jasa, dengan fokus pada layanan, karya, dan kontak.</p><a class="secondary-button" href="/order.html?type=profile&amp;template=Mono">Gunakan template →</a></article><article class="portfolio-card"><div class="portfolio-art"><img src="/assets/rasio-flow.png" alt="Preview dashboard software Rasio Flow" /></div><span class="dummy-badge">Prototipe · Software</span><h2>Rasio Flow</h2><p>Preview dashboard untuk alur pesan dan automasi yang membantu tim menjalankan operasional.</p><a class="secondary-button" href="/layanan-custom.html">Pelajari layanan →</a></article></div>''')
print('Generated Tutorial and Portfolio.')
